#!/usr/bin/env bash
# Install one pinned Soulsteads release into your user account.
set -euo pipefail

usage() {
  printf '%s\n' 'Usage: bash install.sh --list' \
    '       bash install.sh [--dry-run] PRODUCT' \
    '' 'Installs one CLI. Does not configure or start it. Do not use sudo.'
}

die() { printf 'install.sh: %s\n' "$*" >&2; exit 1; }

release_rows() {
  # Generated by scripts/render-lineup.mjs from data/products.json.
  local rows='
# installer-releases
agent-home|soulsteads-agent-home|v0.3.0|soulsteads-0.3.0-py3-none-any.whl|6561dcc75b637e4b995ccadd49d9e88997e8753c5ed66416e04f8d446f0c5546|soulsteads|README.md#get-started|-
agent-messaging|soulsteads-agent-messaging|v0.4.0|soulsteads-agent-messaging-linux-x86_64.tar.gz|bfb0aff6004a37da492ab2de64c6da58eed944bb189d9713027c8d791a8d557a|soulsteads-messaging|docs/SETUP.md#before-you-start|2.39
agent-workboard|soulsteads-agent-workboard|v0.3.0|soulsteads-agent-workboard-linux-x86_64.tar.gz|232f42b00205bdcb731dd924bf25ae5459d96e4028a0877b88b3a7b2f93cb6df|soulsteads-workboard|README.md#quickstart|2.34
model-router|soulsteads-model-router|v0.3.0|soulsteads-model-router-linux-x86_64.tar.gz|0c37339d2f4cb595f04bce535100bb7ec5e1c8a43395eb4e141996d8a6e30a38|soulsteads-router|docs/SETUP.md#prerequisites|2.34
agent-forge|soulsteads-agent-forge|v0.2.0|soulsteads-agent-forge-linux-x86_64.tar.gz|6c09784d4c29c0f7561817dea6977e3ad7159f5fcf8909f44da56476d658e0ee|soulsteads-forge|README.md#quick-start|2.39
agent-skillstore|soulsteads-agent-skillstore|v0.2.0|soulsteads_agent_skillstore-0.2.0-py3-none-any.whl|b59bcdb402f39108e3a83d6ca9dfaf4763b3a448b1762f1762a7ac1e168159b9|skillstore soulsteads-skillstore|README.md#quickstart|-
# end-installer-releases
'
  printf '%s\n' "$rows"
}

if [[ $# == 0 || ( $# == 1 && ( $1 == --help || $1 == -h ) ) ]]; then
  usage; exit 0
fi
if [[ $# == 1 && $1 == --list ]]; then
  while IFS='|' read -r slug repo tag asset digest executables guide min_glibc; do
    [[ -n $repo ]] || continue
    case $asset in
      *.whl) platform='Python 3.11+ and uv';;
      *) platform="Linux x86-64 (glibc $min_glibc+)";;
    esac
    printf '%-18s %-8s %s\n' "$slug" "$tag" "$platform"
  done < <(release_rows)
  exit 0
fi

product= dry_run=0
for arg in "$@"; do
  case $arg in
    --dry-run) [[ $dry_run == 0 ]] || die 'Repeated --dry-run.'; dry_run=1;;
    -*) die "Unknown option: $arg. See --help.";;
    *) [[ -z $product && -n $arg ]] || die 'Select exactly one product. See --list.'; product=$arg;;
  esac
done
[[ -n $product ]] || die 'Select a product. See --list.'

while IFS='|' read -r slug repo tag asset digest executables guide min_glibc; do
  if [[ -n $repo && $product == "$slug" ]]; then break; fi
done < <(release_rows)
[[ -n $repo && $product == "$slug" ]] || die "Unknown product: $product. See --list."
base="https://github.com/soulsteads/$repo"
url="$base/releases/download/$tag/$asset"
setup="$base/blob/$tag/$guide"
[[ ${HOME:-} == /* ]] || die 'HOME must be an absolute path.'
bin_dir=${SOULSTEADS_BIN_DIR:-$HOME/.local/bin}
[[ $bin_dir == /* && $bin_dir != / ]] || die 'SOULSTEADS_BIN_DIR must be an absolute user-owned directory, not /.'
wheel_dir=${XDG_DATA_HOME:-$HOME/.local/share}/soulsteads/wheels
case $asset in
  *.whl) method='Python wheel (Python 3.11+ and uv)';;
  *) method="Prebuilt binary (Linux x86-64, glibc $min_glibc+)";;
esac

if [[ $dry_run == 1 ]]; then
  printf '%s %s\nMethod: %s\nDownload: %s\nSHA-256: %s\nCommands: %s\nBin directory: %s\n' \
    "$product" "$tag" "$method" "$url" "$digest" "$executables" "$bin_dir"
  if [[ $asset == *.whl ]]; then printf 'Verified wheel cache: %s\n' "$wheel_dir"; fi
  printf 'Setup guide: %s\nDry run: no downloads or changes.\n' "$setup"
  exit 0
fi

require() { command -v "$1" >/dev/null || die "Missing $1. Setup guide: $setup"; }

[[ $EUID != 0 ]] || die 'Run as your normal user, not root or sudo.'
require stat
if stat -c '%u %a %d:%i' / >/dev/null 2>&1; then
  stat_args=(-c '%u %a %d:%i')
else
  stat_args=(-f '%u %Lp %d:%i')
fi

# Trust only this user and root in the install path. No other account may
# replace a path component. This is not isolation from the installing UID.
install_directory() {
  local path=$1 action=${2:-check} rest part next parent=/ owner=0 mode metadata identity
  local error="Unsafe install directory: $path. Use an absolute user-owned path without symlink or group/world-writable components."
  if [[ $action == temp ]]; then
    error="Unsafe temporary directory: $path. Set TMPDIR to a private directory you own or use the system temporary directory."
  fi
  [[ $path == /* && $path != */ && $path != *//* && $path != *$'\n'* && $path != *$'\r'* ]] || die "$error"
  rest=${path#/}
  while [[ -n $rest ]]; do
    part=${rest%%/*}
    if [[ $rest == */* ]]; then rest=${rest#*/}; else rest=; fi
    [[ $part != . && $part != .. ]] || die "$error"
    next=${parent%/}/$part
    [[ ! -L $next ]] || die "$error"
    if [[ ! -e $next ]]; then
      [[ $owner == "$EUID" && $action != existing && $action != temp ]] || die "$error"
      if [[ $action == create ]]; then
        # Concurrent installs may have made the same directory. Check it below.
        mkdir -m 700 -- "$next" 2>/dev/null || [[ -d $next ]] || die "Cannot create install directory: $next"
      else
        parent=$next
        continue
      fi
    fi
    [[ -d $next && ! -L $next ]] || die "$error"
    metadata=$(stat "${stat_args[@]}" "$next") || die "$error"
    read -r owner mode identity <<< "$metadata"
    [[ $mode =~ ^[0-7]{1,4}$ && ( $owner == 0 || $owner == "$EUID" ) ]] || die "$error"
    # Only the download scratch parent may be a root-owned sticky directory.
    if [[ $action == temp && -z $rest && $owner == 0 ]] && (( (8#$mode & 01000) != 0 )); then return; fi
    (( (8#$mode & 0022) == 0 )) || die "$error"
    parent=$next
  done
  [[ $owner == "$EUID" ]] || die "$error"
  if [[ $action == create || $action == existing ]]; then printf '%s\n' "$identity"; fi
}

install_directory "$bin_dir"
require curl
if command -v sha256sum >/dev/null; then
  hash_command=(sha256sum)
else
  require shasum
  hash_command=(shasum -a 256)
fi

if [[ $asset == *.whl ]]; then
  install_directory "$wheel_dir"
  require uv
else
  requirement="The prebuilt binary requires Linux x86-64 with glibc $min_glibc or newer. Setup guide: $setup"
  [[ $(uname -s) == Linux && $(uname -m) == x86_64 ]] || die "$requirement"
  glibc=$(getconf GNU_LIBC_VERSION 2>/dev/null) || die "$requirement"
  [[ $glibc =~ ^glibc\ ([0-9]{1,2})\.([0-9]{1,3})(\.[0-9]+)?$ ]] || die "$requirement"
  major=${BASH_REMATCH[1]} minor=${BASH_REMATCH[2]}
  required_major=${min_glibc%.*} required_minor=${min_glibc#*.}
  (( 10#$major > 10#$required_major || (10#$major == 10#$required_major && 10#$minor >= 10#$required_minor) )) || die "$requirement"
  require tar
fi

umask 077
temp_dir=${TMPDIR:-/tmp}
[[ $temp_dir == /* ]] || die 'TMPDIR must be an absolute path.'
# macOS spells its system temp paths through /var or /tmp symlinks. Resolve
# this one path and then use only the validated physical directory.
temp_dir=$(cd -P -- "$temp_dir" && pwd -P) || die 'Could not resolve TMPDIR.'
install_directory "$temp_dir" temp
work=$(mktemp -d "$temp_dir/soulsteads-install.XXXXXXXX")
trap 'rm -rf -- "$work"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

printf 'Downloading %s %s…\n' "$product" "$tag" >&2
curl -q --fail --silent --show-error --location --proto '=https' --proto-redir '=https' \
  --connect-timeout 15 --max-time 300 --max-filesize 268435456 --output "$work/$asset" "$url" \
  || die "Download failed: $url"
actual=$("${hash_command[@]}" < "$work/$asset")
[[ ${actual%% *} == "$digest" ]] || die "SHA-256 mismatch for $asset; nothing installed."

# Stage in the destination directory's filesystem, then publish with a hard
# link to the directory, not to a replaceable destination pathname.
publish_file() (
  source=$1 directory=$2 mode=$3
  name=${source##*/}
  destination=$directory/$name
  identity=$(install_directory "$directory" create)
  cd -P -- "$directory"
  [[ $(stat "${stat_args[@]}" .) == *" $identity" ]] || die "Install directory changed: $directory"
  stage=$(mktemp -d ./.soulsteads-install.XXXXXXXX)
  trap 'rm -rf -- "$stage"' EXIT
  install -m "$mode" -- "$source" "$stage/$name"
  [[ $(install_directory "$directory" existing) == "$identity" ]] || die "Install directory changed: $directory"
  if ln -- "$stage/$name" . 2>/dev/null; then
    [[ ! -L $name && $name -ef $stage/$name && $(install_directory "$directory" existing) == "$identity" ]] \
      || die "Could not verify publication: $destination"
    return
  fi
  if [[ -f $name && ! -L $name && ( $mode != 0755 || -x $name ) ]] &&
    cmp -s -- "$source" "./$name" && [[ $(install_directory "$directory" existing) == "$identity" ]]; then
    return
  fi
  if [[ -e $name || -L $name ]]; then
    die "Refusing to overwrite $destination. Move the existing entry aside and retry if you want this release."
  fi
  die "Could not publish $destination. Check the destination permissions and filesystem."
)

if [[ $asset == *.whl ]]; then
  # Wheel distribution names use underscores in place of package-name hyphens.
  package=${asset%%-*}
  package=${package//_/-}
  tool_root=$(uv tool dir --no-config) || die 'Could not locate the uv tool directory.'
  install_directory "$tool_root/$package/bin"
  IFS=' ' read -r -a commands <<< "$executables"
  for name in "${commands[@]}"; do
    entry=$bin_dir/$name
    if [[ ( -e $entry || -L $entry ) && ! $entry -ef $tool_root/$package/bin/$name ]]; then
      die "Refusing to overwrite $entry. Choose another bin directory or move the existing entry aside."
    fi
  done
  # uv records the local wheel path in its tool receipt, so keep it available.
  publish_file "$work/$asset" "$wheel_dir" 0644
  bin_identity=$(install_directory "$bin_dir" create)
  install_directory "$wheel_dir" existing >/dev/null
  install_directory "$tool_root/$package/bin"
  TMPDIR="$work" UV_TOOL_BIN_DIR="$bin_dir" uv tool install --no-config --no-cache --no-build \
    --no-python-downloads --python '>=3.11' "$wheel_dir/$asset" \
    || die "uv could not install $product. Setup guide: $setup"
  [[ $(install_directory "$bin_dir" existing) == "$bin_identity" ]] || die "Install directory changed: $bin_dir"
  install_directory "$tool_root/$package/bin" existing >/dev/null
  for name in "${commands[@]}"; do
    entry=$bin_dir/$name
    if [[ ! -x $entry || ! $entry -ef $tool_root/$package/bin/$name ]]; then
      die "uv did not put $name in $bin_dir. If already installed, use its existing bin directory or run 'uv tool uninstall $package' before reinstalling."
    fi
  done
else
  # Read only the expected binary member; do not unpack into the home directory.
  (unset TAR_OPTIONS; tar -xOzf "$work/$asset" -- "${asset%.tar.gz}/$executables") > "$work/$executables" \
    || die "Could not extract $executables from $asset."
  [[ -s $work/$executables ]] || die "Missing executable in $asset."
  publish_file "$work/$executables" "$bin_dir" 0755
fi

printf 'Installed %s %s: %s\nBin directory: %s\nSetup guide: %s\n' "$product" "$tag" "$executables" "$bin_dir" "$setup"
case ":$PATH:" in
  *":$bin_dir:"*) ;;
  *) printf 'Add this directory to PATH in your shell: %s\n' "$bin_dir";;
esac
